const Child = React.memo(({ config }) => {
  console.log("Child render");
  return <div style={{ color: config.color }}>{config.theme}</div>;
});

function Parent() {
  const [count, setCount] = useState(0);
  // 注意這裡
  const config = { theme: "dark", color: "red" }; 

  return (
    <div onClick={() => setCount(c => c + 1)}>
      <p>Count: {count}</p>
      <Child config={config} />
    </div>
  );
}

function Parent() {
  const [text, setText] = useState("");

  // Anti-pattern: Defining component inside render
  function InputField() {
    return <input autoFocus />;
  }

  return (
    <div>
      <input value={text} onChange={e => setText(e.target.value)} />
      <InputField />
    </div>
  );
}
